<?php

/**
 * GtuCountryTable
 * 
 * This class has been auto-generated by the Doctrine ORM Framework
 */
class GtuCountryTable extends DarwinTable
{
    /**
     * Returns an instance of this class.
     *
     * @return GtuCountryTable The table instance
     */
    public static function getInstance()
    {
        return Doctrine_Core::getTable('GtuCountry');
    }
	
	public function getDistinctLanguages() 
	{
		$q = $this->createFlatDistinct('gtu_country', 'lang', 'lang');
		$a = DarwinTable::CollectionToArray($q->execute(), 'lang');
		return array_merge(array(''=>''),$a);
	}
	
	public function getSortedIso3166()
	{
		 $q = Doctrine_Query::create()->from("GtuCountry")->addOrderBy("iso3166");
		 return $q->execute();
	}
	
	public function findCountries($term)
	{
		
		$sql="select iso3166 as id, iso3166||' - '||name_en as text FROM gtu_country g WHERE lower(iso3166) LIKE  CONCAT('%', :term, '%')OR lower(name_en) LIKE '%'||:term||'%'  OR lower(name_1) LIKE '%'||:term||'%' OR  lower(name_2) LIKE '%'||:term||'%'OR  lower(name_3) LIKE '%'||:term||'%' OR  lower(name_4) LIKE '%'||:term||'%' OR lower(historical_name_1) LIKE '%'||:term||'%' OR  lower(historical_name_2) LIKE '%'||:term||'%' OR  lower(historical_name_3) LIKE '%'||:term||'%' OR  lower(historical_name_4) LIKE '%'||:term||'%' ORDER BY name_en ;";
		$conn_MGR = Doctrine_Manager::connection();
        $conn = $conn_MGR->getDbh();
		$stmt=$conn->prepare($sql);
        $stmt->bindValue(":term", strtolower(trim($term)));
		
		$stmt->execute();
        $rs=$stmt->fetchAll(PDO::FETCH_ASSOC);
		$res_json=Array();
		
		foreach($rs as $rec)
		{
			$res_json[]=$rec;
		}
		
		return $res_json;		
	}
}